typedef bool (*check_fn)(void *ctx, const void *value);
struct validator { check_fn fn; void *ctx; };

static bool positive(void *ctx, const void *v) {
    return *(const int *)v > 0;                 /* contramap: the cast lives here */
}
static bool both(void *ctx, const void *v) {    /* divide */
    const struct validator *pair = ctx;
    return pair[0].fn(pair[0].ctx, v) && pair[1].fn(pair[1].ctx, v);
}
